SELECT
/* isry.pubms.casemng.sheltrreg.mapper.DgnssReptMapper.selectLinkRcptPagingList */ T1.* FROM ( SELECT /*+ INDEX_DESC(A SEB400_IX01)*/ A.SRVC_PVSN_RQST_NO , A.RESRCE_NO , A.HPE_SRVC_YN , A.RQST_UNT_TASKWK_SE_CD , A.RCPT_RQST_COURS_SE_CD , A.RQST_YMD , A.CLINT_NO , C##RG.DEC_B64(A1.FLNM_ENCPT) AS CLINT_NM , A.RQST_CS_CN , A.PRNMNT_USE_BGNG_YMD , A.PRNMNT_USE_BGNG_HR , A.PRNMNT_USE_END_YMD , A.PRNMNT_USE_END_HR , A.RCPT_UNT_TASKWK_SE_CD , A.CLR_NO , C##RG.DEC_B64(A2.FLNM_ENCPT) AS CLR_NM , A.RCPT_INST_NO , A3.INST_NM AS RCPT_INST_NM , A.RQST_TRPR_INFO_NO , C##RG.DEC_B64(A4.TRPR_NM_ENCPT) AS RQST_TRPR_INFO_NM , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , A.RQST_APLY_YN , A.RQST_DTL_CN , A.LINK_TYPE_SE_CD , A.TRMN_PRCS_YN , A.RQST_INST_NO , A5.INST_NM AS RQST_INST_NM , B.RCPT_SE_CD , B.RCPT_TRPR_INFO_NO , B.RCPT_DTL_CN , B.RCPT_YMD /* , (SELECT RCPT_YMD FROM SEB421 WHERE SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO AND RCPT_SE_CD = B.RCPT_SE_CD AND RCPT_UNT_TASKWK_SE_CD = B.RCPT_UNT_TASKWK_SE_CD AND MDFCN_DT = (SELECT MIN(MDFCN_DT) FROM SEB421 WHERE SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO AND RCPT_SE_CD = B.RCPT_SE_CD AND RCPT_UNT_TASKWK_SE_CD = B.RCPT_UNT_TASKWK_SE_CD)) AS FIRST_RCPT_YMD */ , CASE WHEN C.INTRVN_STTS_SE_CD IS NOT NULL THEN C.INTRVN_STTS_SE_CD WHEN D.INTRVN_STTS_SE_CD IS NOT NULL THEN D.INTRVN_STTS_SE_CD ELSE NULL END AS INTRVN_STTS_SE_CD , CASE WHEN C.SCHL_NM IS NOT NULL THEN C.SCHL_NM WHEN D.SCHL_NM IS NOT NULL THEN D.SCHL_NM ELSE NULL END AS SCHL_NM , CASE WHEN C.PRTCR_FLNM_ENCPT IS NOT NULL THEN C##RG.DEC_B64(C.PRTCR_FLNM_ENCPT) WHEN D.PRTCR_FLNM_ENCPT IS NOT NULL THEN C##RG.DEC_B64(D.PRTCR_FLNM_ENCPT) ELSE NULL END AS PRTCR_FLNM , CASE WHEN C.PRTCR_TELNO_ENCPT IS NOT NULL THEN C##RG.DEC_B64(C.PRTCR_TELNO_ENCPT) WHEN D.PRTCR_TELNO_ENCPT IS NOT NULL THEN C##RG.DEC_B64(D.PRTCR_TELNO_ENCPT) ELSE NULL END AS PRTCR_TELNO , CASE WHEN C.SXDC_SE_CD IS NOT NULL THEN C.SXDC_SE_CD WHEN D.SXDC_SE_CD IS NOT NULL THEN D.SXDC_SE_CD ELSE NULL END AS SXDC_SE_CD , CASE WHEN C.INTNET_SRVY_RESULT_CN IS NOT NULL THEN C.INTNET_SRVY_RESULT_CN ELSE NULL END AS INTNET_SRVY_RESULT_CN , CASE WHEN C.SMRTP_SRVY_RESULT_CN IS NOT NULL THEN C.SMRTP_SRVY_RESULT_CN ELSE NULL END AS SMRTP_SRVY_RESULT_CN , CASE WHEN C.OBSRVR_DGNSS_RESULT_CN IS NOT NULL THEN C.OBSRVR_DGNSS_RESULT_CN ELSE NULL END AS OBSRVR_DGNSS_RESULT_CN , CASE WHEN C.GAMBLE_SRVY_RESULT_CN IS NOT NULL THEN C.GAMBLE_SRVY_RESULT_CN ELSE NULL END AS GAMBLE_SRVY_RESULT_CN , CASE WHEN C.ADDTNG_TRL_INSP_YN IS NOT NULL THEN C.ADDTNG_TRL_INSP_YN WHEN D.ADDTNG_TRL_INSP_YN IS NOT NULL THEN D.ADDTNG_TRL_INSP_YN ELSE NULL END AS ADDTNG_TRL_INSP_YN , ROWNUM AS SEQ FROM SEB400 A , SCA100 A1 , SCA100 A2 , SAA000 A3 , SEA200 A4 , SAA000 A5 , SEB420 B , ACA210 C , ACA400 D WHERE A.CLINT_NO = A1.ENFSN_NO(+) AND A.CLR_NO = A2.ENFSN_NO(+) AND A.RCPT_INST_NO = A3.INST_NO AND A.RQST_TRPR_INFO_NO = A4.TRPR_INFO_NO AND A.RQST_INST_NO = A5.INST_NO AND A.RQST_YMD BETWEEN #{PRNMNT_USE_BGNG_YMD} AND #{PRNMNT_USE_END_YMD} AND A.SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO AND B.RCPT_SN = (CASE WHEN B.RCPT_SE_CD = '40' THEN (SELECT MAX(RCPT_SN) FROM SEB420 WHERE SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO AND RCPT_UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}) ELSE ((SELECT MAX(RCPT_SN) FROM SEB420 WHERE SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO) )END)
AND A5.INST_NM LIKE '%' || #{RQST_INST_NM} || '%'
AND A3.INST_NM LIKE '%' || #{RCPT_INST_NM} || '%'
AND B.RCPT_TRPR_INFO_NO = C.TRPR_INFO_NO(+) AND B.RCPT_TRPR_INFO_NO = D.TRPR_INFO_NO(+)
) T1 WHERE 1 = 1
AND T1.SEQ >= #{START_IDX} AND T1.SEQ <= #{LAST_IDX}

