mapper.select:
/* selectDgnssScoreList - Lee MS */
WITH AA AS ( SELECT A.DGNSS_EXMN_MNG_NO AS DGNSS_EXMN_MNG_NO, A.DGNSS_EXMN_SE_CD AS DGNSS_EXMN_SE_CD, /* 진단조사구분코드 */ SUM(DECODE(A.SCORE_SE_SE_CD, '001', DGNSS_SCORE)) AS DGNSS_SCORE01, SUM(DECODE(A.SCORE_SE_SE_CD, '002', DGNSS_SCORE)) AS DGNSS_SCORE02, SUM(DECODE(A.SCORE_SE_SE_CD, '003', DGNSS_SCORE)) AS DGNSS_SCORE03, SUM(DECODE(A.SCORE_SE_SE_CD, '004', DGNSS_SCORE)) AS DGNSS_SCORE04, SUM(DECODE(A.SCORE_SE_SE_CD, '005', DGNSS_SCORE)) AS DGNSS_SCORE05, SUM(DECODE(A.SCORE_SE_SE_CD, '006', DGNSS_SCORE)) AS DGNSS_SCORE06, SUM(DECODE(A.SCORE_SE_SE_CD, '007', DGNSS_SCORE)) AS DGNSS_SCORE07, SUM(DECODE(A.SCORE_SE_SE_CD, '008', DGNSS_SCORE)) AS DGNSS_SCORE08, SUM(DECODE(A.SCORE_SE_SE_CD, '009', DGNSS_SCORE)) AS DGNSS_SCORE09, SUM(DECODE(A.SCORE_SE_SE_CD, '010', DGNSS_SCORE)) AS DGNSS_SCORE10, SUM(DECODE(A.SCORE_SE_SE_CD, '011', DGNSS_SCORE)) AS DGNSS_SCORE11, SUM(DECODE(A.SCORE_SE_SE_CD, '012', DGNSS_SCORE)) AS DGNSS_SCORE12, SUM(DECODE(A.SCORE_SE_SE_CD, '013', DGNSS_SCORE)) AS DGNSS_SCORE13, SUM(DECODE(A.SCORE_SE_SE_CD, '014', DGNSS_SCORE)) AS DGNSS_SCORE14, SUM(DECODE(A.SCORE_SE_SE_CD, '015', DGNSS_SCORE)) AS DGNSS_SCORE15, SUM(DGNSS_SCORE) AS DGNSS_SCORETOT FROM ACA410 A /* 진단조사구분코드 - 인터넷자가, 스마트폰자가, 인터넷관찰, 스마트폰관찰 */ WHERE A.DGNSS_EXMN_MNG_NO = #{DGNSS_EXMN_MNG_NO} AND A.DGNSS_EXMN_SE_CD IN ('1', '2', '3', '4') AND A.CASE_PRGRS_STTS_TYPE_SE_CD = #{CASE_PRGRS_STTS_TYPE_SE_CD} GROUP BY A.DGNSS_EXMN_MNG_NO, A.DGNSS_EXMN_SE_CD ), AAA AS ( SELECT AA.*, CASE WHEN BB.DGNSS_EXMN_MNG_NO IS NOT NULL THEN /* 미디어과의존대상자-학년구분 */ CASE WHEN BB.MEDIAA_SCHL_SE_CD = '1' THEN '1' ELSE '2' END WHEN CC.DGNSS_EXMN_MNG_NO IS NOT NULL THEN /* 학교진단 -학년구분*/ CASE WHEN CC.MEDIAA_SCHL_SE_CD = '1' THEN '1' ELSE '2' END WHEN DD.DGNSS_EXMN_MNG_NO IS NOT NULL THEN /* 기관진단-학년구분 */ CASE WHEN DD.STDNT_AGE_NM = '1' THEN '1' ELSE '2' END ELSE '2' END AS STDNT_AGE_NM, /*학년구분 */ CASE WHEN AA.DGNSS_EXMN_SE_CD IN ('1', '3') THEN DGNSS_SCORE01 + DGNSS_SCORE05 + DGNSS_SCORE09 + DGNSS_SCORE12 + DGNSS_SCORE15 ELSE DGNSS_SCORE01 + DGNSS_SCORE05 + DGNSS_SCORE09 + DGNSS_SCORE12 + DGNSS_SCORE13 END AS DGNSS_SCOREA1, CASE WHEN AA.DGNSS_EXMN_SE_CD IN ('1', '3') THEN DGNSS_SCORE03 + DGNSS_SCORE07 + DGNSS_SCORE10 + DGNSS_SCORE13 ELSE DGNSS_SCORE03 + DGNSS_SCORE07 + DGNSS_SCORE10 + DGNSS_SCORE14 END AS DGNSS_SCOREA2, CASE WHEN AA.DGNSS_EXMN_SE_CD IN ('1', '3') THEN DGNSS_SCORE04 + DGNSS_SCORE08 + DGNSS_SCORE11 + DGNSS_SCORE14 ELSE DGNSS_SCORE04 + DGNSS_SCORE08 + DGNSS_SCORE11 + DGNSS_SCORE15 END AS DGNSS_SCOREA3, DGNSS_SCORE02 + DGNSS_SCORE06 AS DGNSS_SCOREA4 FROM AA, ACA200 BB, ACA210 CC, ACA400 DD WHERE AA.DGNSS_EXMN_MNG_NO = BB.DGNSS_EXMN_MNG_NO(+) AND AA.DGNSS_EXMN_MNG_NO = CC.DGNSS_EXMN_MNG_NO(+) AND AA.DGNSS_EXMN_MNG_NO = DD.DGNSS_EXMN_MNG_NO(+) ), AAAA AS ( SELECT AAA.*, CASE WHEN AAA.DGNSS_EXMN_SE_CD IN ('1') THEN /* 인터넷진단-자가진단 */ CASE WHEN AAA.STDNT_AGE_NM = '1' THEN /* 초등학교 */ CASE WHEN AAA.DGNSS_SCORETOT >= 42 THEN '1' WHEN AAA.DGNSS_SCOREA1 >= 14 AND AAA.DGNSS_SCOREA2 >= 13 AND AAA.DGNSS_SCOREA3 >= 13 THEN '1' WHEN AAA.DGNSS_SCORETOT < 42 AND AAA.DGNSS_SCORETOT >= 39 THEN '2' WHEN AAA.DGNSS_SCOREA1 >= 13 OR AAA.DGNSS_SCOREA2 >= 12 OR AAA.DGNSS_SCOREA3 >= 11 THEN '2' ELSE '3' END ELSE /* 중고등학교*/ CASE WHEN AAA.DGNSS_SCORETOT >= 44 THEN '1' WHEN AAA.DGNSS_SCOREA1 >= 15 AND AAA.DGNSS_SCOREA2 >= 13 AND AAA.DGNSS_SCOREA3 >=14 THEN '1' WHEN AAA.DGNSS_SCORETOT < 44 AND AAA.DGNSS_SCORETOT >= 41 THEN '2' WHEN AAA.DGNSS_SCOREA1 >= 14 OR AAA.DGNSS_SCOREA2 >= 12 OR AAA.DGNSS_SCOREA3 >= 12 THEN '2' ELSE '3' END END WHEN AAA.DGNSS_EXMN_SE_CD IN ('3') THEN /* 인터넷진단 -관찰자진단*/ CASE WHEN AAA.STDNT_AGE_NM = '1' THEN /* 초등학교 */ CASE WHEN AAA.DGNSS_SCORETOT >= 30 THEN '1' WHEN AAA.DGNSS_SCOREA1 >= 14 AND AAA.DGNSS_SCOREA2 >= 12 AND AAA.DGNSS_SCOREA3 >= 11 THEN '1' WHEN AAA.DGNSS_SCORETOT < 30 AND AAA.DGNSS_SCORETOT >= 28 THEN '2' WHEN AAA.DGNSS_SCOREA1 >= 13 OR AAA.DGNSS_SCOREA2 >= 11 OR AAA.DGNSS_SCOREA3 >= 10 THEN '2' ELSE '3' END ELSE /* 중고등학교*/ CASE WHEN AAA.DGNSS_SCORETOT >= 35 THEN '1' WHEN AAA.DGNSS_SCOREA1 >= 14 AND AAA.DGNSS_SCOREA2 >= 12 AND AAA.DGNSS_SCOREA3 >= 11 THEN '1' WHEN AAA.DGNSS_SCORETOT < 35 AND AAA.DGNSS_SCORETOT >= 32 THEN '2' WHEN AAA.DGNSS_SCOREA1 >= 13 OR AAA.DGNSS_SCOREA2 >= 11 OR AAA.DGNSS_SCOREA3 >= 10 THEN '2' ELSE '3' END END ELSE /* 스마트폰진단 */ CASE WHEN AAA.DGNSS_SCORETOT >= 45 THEN '1' WHEN AAA.DGNSS_SCOREA1 >= 16 AND AAA.DGNSS_SCOREA2 >= 13 AND AAA.DGNSS_SCOREA3 >=14 THEN '1' WHEN AAA.DGNSS_SCORETOT < 45 AND AAA.DGNSS_SCORETOT >= 42 THEN '2' WHEN AAA.DGNSS_SCOREA1 >= 14 OR AAA.DGNSS_SCOREA2 >= 12 OR AAA.DGNSS_SCOREA3 >= 13 THEN '2' ELSE '3' END END AS DGNSS_SCOREAR FROM AAA )
SELECT * FROM AAAA ORDER BY DGNSS_EXMN_SE_CD

/* selectCyberGambleList - Lee MS */
WITH AA AS ( SELECT A.DGNSS_EXMN_MNG_NO AS DGNSS_EXMN_MNG_NO, A.DGNSS_EXMN_SE_CD AS DGNSS_EXMN_SE_CD, /* 진단조사구분코드 */ SUM(DECODE(A.SCORE_SE_SE_CD, '001', DGNSS_SCORE)) AS DGNSS_SCORE01, SUM(DECODE(A.SCORE_SE_SE_CD, '002', DGNSS_SCORE)) AS DGNSS_SCORE02, SUM(DECODE(A.SCORE_SE_SE_CD, '003', DGNSS_SCORE)) AS DGNSS_SCORE03, SUM(DECODE(A.SCORE_SE_SE_CD, '004', DGNSS_SCORE)) AS DGNSS_SCORE04, SUM(DECODE(A.SCORE_SE_SE_CD, '005', DGNSS_SCORE)) AS DGNSS_SCORE05, SUM(DECODE(A.SCORE_SE_SE_CD, '006', DGNSS_SCORE)) AS DGNSS_SCORE06, SUM(DECODE(A.SCORE_SE_SE_CD, '007', DGNSS_SCORE)) AS DGNSS_SCORE07, SUM(DECODE(A.SCORE_SE_SE_CD, '008', DGNSS_SCORE)) AS DGNSS_SCORE08, SUM(DECODE(A.SCORE_SE_SE_CD, '009', DGNSS_SCORE)) AS DGNSS_SCORE09, SUM(DECODE(A.SCORE_SE_SE_CD, '010', DGNSS_SCORE)) AS DGNSS_SCORE10, SUM(DGNSS_SCORE) AS DGNSS_SCORETOT FROM ACA410 A /* 진단조사구분코드 - 사이버도박 */ WHERE A.DGNSS_EXMN_MNG_NO = #{DGNSS_EXMN_MNG_NO} AND A.DGNSS_EXMN_SE_CD IN ('6') AND A.CASE_PRGRS_STTS_TYPE_SE_CD = #{CASE_PRGRS_STTS_TYPE_SE_CD} GROUP BY A.DGNSS_EXMN_MNG_NO, A.DGNSS_EXMN_SE_CD )
SELECT AA.*, CASE WHEN AA.DGNSS_SCORETOT >= 5 THEN '1' WHEN AA.DGNSS_SCORETOT < 5 AND AA.DGNSS_SCORETOT >= 1 THEN '2' ELSE '3' END AS DGNSS_SCOREAR FROM AA

mapper.update:
UPDATE SEA200
   SET CASE_MNG_SE_CD = #{CASE_MNG_SE_CD} 
     , CASE_TRPR_NOAP_CS_SE_CD = #{CASE_TRPR_NOAP_CS_SE_CD}

     , CASE_TRPR_UNSL_CS_CN = #{CASE_TRPR_UNSL_CS_CN}


    , RCPT_PIC_NO = #{RCPT_PIC_NO}


    , RCPT_INST_NO = #{RCPT_INST_NO}

WHERE TRPR_INFO_NO = #{TRPR_INFO_NO}

	    UPDATE SEB420
	       SET RCPT_SE_CD = #{RCPT_SE_CD}
	         , LAST_MDFR_ID = #{USER_ID}
	         , LAST_MDFCN_DT = SYSDATE
	     WHERE SRVC_PVSN_RQST_NO = #{SRVC_PVSN_RQST_NO}
           AND RCPT_SN = (SELECT MAX(RCPT_SN) FROM SEB420 WHERE SRVC_PVSN_RQST_NO = #{SRVC_PVSN_RQST_NO})
